## ===========================================================================
##  Statistics of multivariate extremes under random censoring
##  Martin Bladt
##
##  application.R -- flood losses censored by policy limits.
##
##  Building and contents indemnities from the claims generated by Hurricane
##  Ian, as recorded in the OpenFEMA National Flood Insurance Program claims
##  file.  A payment is censored exactly when it equals its coverage limit, so
##  the recorded pair is the observation scheme of the paper in d = 2.
##
##  Output (written to figures/ and results/):
##
##    Figure 3   hurricane_ian_analysis.pdf   paper, Section 5.3
##    Figure 4   hurricane_ian_checks.pdf     paper, Section 5.3
##    results/hurricane_ian_*.csv             every number quoted in Section 5
##
##  The claims file is downloaded from the OpenFEMA API on first use and
##  cached, so the script needs an internet connection once.  Set the
##  environment variable IAN_CACHE to a path if you would rather keep the
##  cache somewhere permanent; by default it goes to the session temporary
##  directory.
##
##  Running time is a few minutes, most of it the download.
## ===========================================================================

script_file <- grep("^--file=", commandArgs(FALSE), value = TRUE)
root <- if (length(script_file)) {
  dirname(normalizePath(sub("^--file=", "", script_file[1L])))
} else {
  getwd()
}
source(file.path(root, "functions.R"))
required_packages(c("jsonlite", "cowplot"))

result_dir <- file.path(root, "results")
figure_dir <- file.path(root, "figures")
dir.create(result_dir, recursive = TRUE, showWarnings = FALSE)
dir.create(figure_dir, recursive = TRUE, showWarnings = FALSE)



## -------------------------------------------------------------------------
## Data acquisition
## -------------------------------------------------------------------------

ian_fields <- c(
  "id", "dateOfLoss", "state", "countyCode", "censusTract",
  "occupancyType", "primaryResidenceIndicator", "condominiumCoverageTypeCode",
  "numberOfUnits", "replacementCostBasis", "buildingReplacementCost",
  "contentsReplacementCost", "buildingPropertyValue", "contentsPropertyValue",
  "totalBuildingInsuranceCoverage", "totalContentsInsuranceCoverage",
  "buildingDeductibleCode", "contentsDeductibleCode",
  "netBuildingPaymentAmount", "netContentsPaymentAmount",
  "amountPaidOnBuildingClaim", "amountPaidOnContentsClaim",
  "buildingDamageAmount", "contentsDamageAmount",
  "postFIRMConstructionIndicator", "elevatedBuildingIndicator",
  "ratedFloodZone", "latitude", "longitude", "rateMethod", "policyCount",
  "originalConstructionDate"
)

download_ian_claims <- function() {
  endpoint <- "https://www.fema.gov/api/open/v2/FimaNfipClaims"
  event_filter <- utils::URLencode("floodEvent eq 'Hurricane Ian'", reserved = TRUE)
  pages <- list()

  for (skip in seq(0L, 100000L, by = 10000L)) {
    query <- paste0(
      "%24filter=", event_filter,
      "&%24top=10000&%24skip=", skip,
      "&%24select=", paste(ian_fields, collapse = ",")
    )
    page <- jsonlite::fromJSON(paste0(endpoint, "?", query))$FimaNfipClaims
    if (is.null(page) || !NROW(page)) break
    pages[[length(pages) + 1L]] <- page
    if (NROW(page) < 10000L) break
  }
  do.call(rbind, pages)
}

cache_file <- Sys.getenv(
  "IAN_CACHE", file.path(tempdir(), "hurricane_ian_nfip_claims_v2.rds")
)
if (file.exists(cache_file)) {
  claims <- readRDS(cache_file)
} else {
  claims <- download_ian_claims()
  saveRDS(claims, cache_file, compress = "xz")
}


## -------------------------------------------------------------------------
## Cohort and observation scheme
##
## X = the indemnity that coverage j would have paid in the absence of the
##     policy limit; C = the policy limit; Z = the recorded net payment.
## -------------------------------------------------------------------------

deductible <- c(
  "0" = 500, "1" = 1000, "2" = 2000, "3" = 3000, "4" = 4000,
  "5" = 5000, "9" = 750, "A" = 10000, "B" = 15000, "C" = 20000,
  "D" = 25000, "E" = 50000, "F" = 1250, "G" = 1500, "H" = 200
)
claims$building_deductible <- unname(deductible[as.character(claims$buildingDeductibleCode)])
claims$contents_deductible <- unname(deductible[as.character(claims$contentsDeductibleCode)])

## The last two payment conditions are a data-consistency screen, not part of the
## cohort definition: a payment above its own limit is impossible under Z = X ^ C and
## records an error (52 of 3826 rows).  The one-dollar tolerance keeps the equality
## case, which is exactly the censored observation.
selection <- with(
  claims,
  state == "FL" & countyCode %in% "12071" & occupancyType == 11 &
    primaryResidenceIndicator %in% TRUE & condominiumCoverageTypeCode %in% "N" &
    policyCount == 1 & replacementCostBasis %in% "R" &
    totalBuildingInsuranceCoverage > 0 & totalContentsInsuranceCoverage > 0 &
    netBuildingPaymentAmount > 0 & netContentsPaymentAmount > 0 &
    netBuildingPaymentAmount <= totalBuildingInsuranceCoverage + 1 &
    netContentsPaymentAmount <= totalContentsInsuranceCoverage + 1 &
    !is.na(building_deductible) & !is.na(contents_deductible)
)
selection[is.na(selection)] <- FALSE

cohort <- claims[selection, , drop = FALSE]
stopifnot(nrow(cohort) > 1000L)

payment <- as.matrix(cohort[c("netBuildingPaymentAmount", "netContentsPaymentAmount")])
coverage <- as.matrix(cohort[c(
  "totalBuildingInsuranceCoverage", "totalContentsInsuranceCoverage"
)])
cap <- abs(payment - coverage) <= 1
z <- payment
z[cap] <- coverage[cap]
delta <- 1L * !cap
colnames(z) <- colnames(delta) <- c("building", "contents")
n <- nrow(z)


## -------------------------------------------------------------------------
## Censoring diagnostics: dependence within C, and independence of X and C
## -------------------------------------------------------------------------

damage <- as.matrix(cohort[c("buildingDamageAmount", "contentsDamageAmount")])
damage_available <- stats::complete.cases(damage) & damage[, 1L] > 0 & damage[, 2L] > 0

## Among capped payments, is the recorded damage informative beyond the limit?
effective_cap <- cbind(
  coverage[, 1L] + cohort$building_deductible,
  coverage[, 2L] + cohort$contents_deductible
)
damage_pinned <- vapply(seq_len(2L), function(j) {
  idx <- delta[, j] == 0L & !is.na(damage[, j])
  mean(damage[idx, j] <= effective_cap[idx, j])
}, numeric(1))
damage_ratio_median <- vapply(seq_len(2L), function(j) {
  idx <- delta[, j] == 0L & !is.na(damage[, j])
  stats::median(damage[idx, j] / coverage[idx, j])
}, numeric(1))

censoring_diagnostic <- data.frame(
  metric = c(
    "coverage_spearman", "both_statutory_maximum", "product_of_marginals",
    "coverage_damage_max_abs_spearman", "damage_available",
    "damage_pinned_building", "damage_pinned_contents",
    "damage_over_coverage_median_building", "damage_over_coverage_median_contents"
  ),
  value = c(
    stats::cor(coverage[, 1L], coverage[, 2L], method = "spearman"),
    mean(coverage[, 1L] == 250000 & coverage[, 2L] == 100000),
    mean(coverage[, 1L] == 250000) * mean(coverage[, 2L] == 100000),
    max(abs(stats::cor(
      coverage[damage_available, , drop = FALSE],
      damage[damage_available, , drop = FALSE], method = "spearman"
    ))),
    sum(damage_available), damage_pinned, damage_ratio_median
  )
)


## -------------------------------------------------------------------------
## Marginal diagnostics: censored Hill estimates and the estimable range
## -------------------------------------------------------------------------

hill_grid <- seq(400L, 1800L, by = 50L)
hill <- do.call(rbind, lapply(hill_grid, function(k) {
  fits <- lapply(seq_len(2L), function(j) censored_weissman(z[, j], delta[, j], k))
  data.frame(
    k = k, coordinate = colnames(z),
    threshold = vapply(fits, `[[`, numeric(1), "threshold_z"),
    gamma = vapply(fits, `[[`, numeric(1), "gamma"),
    uncensored = vapply(fits, `[[`, numeric(1), "p")
  )
}))
utils::write.csv(hill, file.path(result_dir, "hurricane_ian_hill.csv"), row.names = FALSE)

## The Kaplan-Meier estimator of each marginal survival is bounded below by its
## terminal plateau, so the standardized scale is bounded above; this is the
## empirical form of the identifiability restriction imposed by the policy limit.
plateau <- vapply(seq_len(2L), function(j) min(km_fit(z[, j], delta[, j])$survival), numeric(1))
direction_bound <- 2
k_minimum <- ceiling(direction_bound * n * max(plateau))


## -------------------------------------------------------------------------
## Directions and threshold selection
## -------------------------------------------------------------------------

angle <- seq(-log(direction_bound), log(direction_bound), length.out = 13L)
directions <- cbind(exp(pmax(angle, 0)), exp(pmax(-angle, 0)))
reference_index <- which.min(abs(angle))
off_reference <- setdiff(seq_along(angle), reference_index)

k_grid <- seq(from = 25L * ceiling(k_minimum / 25L), to = 1150L, by = 25L)
k_fits <- lapply(k_grid, function(k) {
  directional_km(standardize_km(z, delta, k), delta, directions, conf_level = 0.95)
})
k_estimate <- vapply(k_fits, function(f) f$estimate, numeric(nrow(directions)))
k_sd <- vapply(k_fits, function(f) f$se_log * f$estimate, numeric(nrow(directions)))

## Standardized maximal past deviation, in the spirit of the sequential rule of
## Drees and Kaufmann (1998): the largest k whose estimate has not yet moved away
## from any smaller-threshold estimate by more than c of that estimate's own
## standard deviation.
stability_constant <- 2
stability <- vapply(seq_along(k_grid), function(l) {
  max(vapply(seq_len(l), function(l2) {
    max(abs(k_estimate[off_reference, l] - k_estimate[off_reference, l2]) /
          k_sd[off_reference, l2])
  }, numeric(1)))
}, numeric(1))
exceeding <- which(stability > stability_constant)
k_selected <- if (length(exceeding)) k_grid[max(1L, min(exceeding) - 1L)] else max(k_grid)

threshold_stability <- data.frame(
  k = k_grid, fraction = k_grid / n, statistic = stability,
  effective = vapply(k_fits, function(f) f$effective[reference_index], numeric(1)),
  t(k_estimate)
)
names(threshold_stability)[-(1:4)] <- sprintf("direction%02d", seq_along(angle))
utils::write.csv(
  threshold_stability, file.path(result_dir, "hurricane_ian_threshold.csv"),
  row.names = FALSE
)


## -------------------------------------------------------------------------
## Directional profile at the selected threshold
## -------------------------------------------------------------------------

standardized <- standardize_km(z, delta, k_selected)
profile_fit <- directional_km(standardized, delta, directions, conf_level = 0.95)
profile <- data.frame(
  angle = angle, ratio = exp(angle),
  q_building = directions[, 1L], q_contents = directions[, 2L],
  estimate = profile_fit$estimate, lower = profile_fit$lower,
  upper = profile_fit$upper, se_log = profile_fit$se_log,
  naive = naive_tail(standardized, directions),
  independence = 1 / (directions[, 1L] * directions[, 2L]),
  effective = profile_fit$effective
)
utils::write.csv(
  profile, file.path(result_dir, "hurricane_ian_tail_profiles.csv"), row.names = FALSE
)


## -------------------------------------------------------------------------
## Bootstrap assessment of the plug-in intervals
## -------------------------------------------------------------------------

boot_replicates <- 500L
set.seed(20220928L)
boot <- vapply(seq_len(boot_replicates), function(b) {
  idx <- sample.int(n, n, replace = TRUE)
  zb <- z[idx, , drop = FALSE]
  db <- delta[idx, , drop = FALSE]
  fit <- try(
    directional_km(standardize_km(zb, db, k_selected), db, directions),
    silent = TRUE
  )
  if (inherits(fit, "try-error")) rep(NA_real_, nrow(directions)) else log(fit$estimate)
}, numeric(nrow(directions)))
bootstrap <- data.frame(
  angle = angle, plug_in_sd = profile$se_log,
  bootstrap_sd = apply(boot, 1L, stats::sd, na.rm = TRUE)
)
bootstrap$ratio <- bootstrap$bootstrap_sd / bootstrap$plug_in_sd
utils::write.csv(
  bootstrap, file.path(result_dir, "hurricane_ian_bootstrap.csv"), row.names = FALSE
)


## -------------------------------------------------------------------------
## Joint exceedance probabilities on the monetary scale
## -------------------------------------------------------------------------

physical_thresholds <- rbind(
  c(120000, 25000), c(150000, 35000), c(180000, 45000),
  c(210000, 55000), c(230000, 65000), c(245000, 75000)
)
marginal_fits <- lapply(seq_len(2L), function(j) km_fit(z[, j], delta[, j]))
physical <- do.call(rbind, lapply(seq_len(nrow(physical_thresholds)), function(i) {
  q <- physical_thresholds[i, ]
  fit <- ray_product_limit(z, delta, q, influence = TRUE)
  se <- fit$survival * stats::sd(fit$influence) / sqrt(n)
  marginals <- vapply(seq_len(2L), function(j) {
    km_survival(marginal_fits[[j]], q[j])
  }, numeric(1))
  data.frame(
    order = i, building = q[1L], contents = q[2L], estimate = fit$survival,
    lower = max(0, fit$survival - 1.96 * se),
    upper = min(1, fit$survival + 1.96 * se),
    naive = mean(z[, 1L] > q[1L] & z[, 2L] > q[2L]),
    marginal_product = prod(marginals),
    effective = sum(z[, 1L] >= q[1L] & z[, 2L] >= q[2L])
  )
}))
## Standardization check.  At a fixed dollar pair both standardizations target the
## same probability, since psi_j(X) > psi_j(x) is equivalent to X > x under either map;
## the raw scale used above is the multiplicative one, and the Kaplan-Meier scale is
## obtained by transforming the sample and the threshold by the marginal fits.
psi_km <- function(x, j) (k_selected / n) / pmax(km_survival(marginal_fits[[j]], x), 1e-12)
z_km <- cbind(vapply(z[, 1L], psi_km, numeric(1), j = 1L),
              vapply(z[, 2L], psi_km, numeric(1), j = 2L))
physical$estimate_km <- vapply(seq_len(nrow(physical_thresholds)), function(i) {
  q <- physical_thresholds[i, ]
  ray_product_limit(z_km, delta, c(psi_km(q[1L], 1L), psi_km(q[2L], 2L)))$survival
}, numeric(1))
physical$standardization_ratio <- physical$estimate / physical$estimate_km

physical$ratio_naive <- physical$estimate / physical$naive
physical$ratio_independence <- physical$estimate / physical$marginal_product
utils::write.csv(
  physical, file.path(result_dir, "hurricane_ian_physical_tail.csv"), row.names = FALSE
)

## -------------------------------------------------------------------------
## Summary
## -------------------------------------------------------------------------

summary_values <- data.frame(
  metric = c(
    "all_hurricane_ian_claims", "analysis_cohort",
    "building_censored", "contents_censored",
    "both_coordinates_censored", "any_coordinate_censored",
    "building_at_statutory_maximum", "contents_at_statutory_maximum",
    "km_plateau_building", "km_plateau_contents", "k_minimum",
    "k_selected", "tail_fraction", "reference_effective",
    "hill_building_low", "hill_building_high",
    "hill_contents_low", "hill_contents_high",
    "bootstrap_sd_ratio_median"
  ),
  value = c(
    nrow(claims), n, colMeans(delta == 0), mean(rowSums(delta == 0) == 2),
    mean(rowSums(delta == 0) > 0),
    mean(coverage[, 1L] == 250000), mean(coverage[, 2L] == 100000),
    plateau, k_minimum, k_selected, k_selected / n,
    profile$effective[reference_index],
    hill$gamma[hill$coordinate == "building" & hill$k == min(hill_grid)],
    hill$gamma[hill$coordinate == "building" & hill$k == max(hill_grid)],
    hill$gamma[hill$coordinate == "contents" & hill$k == min(hill_grid)],
    hill$gamma[hill$coordinate == "contents" & hill$k == max(hill_grid)],
    stats::median(bootstrap$ratio[off_reference])
  )
)
summary_values <- rbind(summary_values, censoring_diagnostic)
utils::write.csv(
  summary_values, file.path(result_dir, "hurricane_ian_summary.csv"), row.names = FALSE
)


## -------------------------------------------------------------------------
## Figure
## -------------------------------------------------------------------------

stability_long <- do.call(rbind, lapply(
  list(c(index = 1L, label = "q = (1, 2)"),
       c(index = nrow(directions), label = "q = (2, 1)")),
  function(spec) {
    i <- as.integer(spec["index"])
    data.frame(
      k = k_grid, direction = unname(spec["label"]),
      estimate = k_estimate[i, ],
      lower = k_estimate[i, ] - 1.96 * k_sd[i, ],
      upper = k_estimate[i, ] + 1.96 * k_sd[i, ]
    )
  }
))

p_stability <- ggplot2::ggplot(
  stability_long, ggplot2::aes(k, estimate, colour = direction, fill = direction,
                               linetype = direction)
) +
  ggplot2::geom_ribbon(ggplot2::aes(ymin = lower, ymax = upper), alpha = 0.13,
                       colour = NA) +
  ggplot2::geom_vline(xintercept = k_selected, linewidth = 0.4, colour = "#B00020") +
  ggplot2::geom_line(linewidth = 0.62) +
  ggplot2::scale_colour_manual(values = c(
    "q = (1, 2)" = unname(simulation_palette["proposed"]),
    "q = (2, 1)" = unname(simulation_palette["matched"])
  )) +
  ggplot2::scale_fill_manual(values = c(
    "q = (1, 2)" = unname(simulation_palette["proposed"]),
    "q = (2, 1)" = unname(simulation_palette["matched"])
  )) +
  ggplot2::scale_linetype_manual(values = c("solid", "22")) +
  ggplot2::coord_cartesian(ylim = c(0.45, 0.82)) +
  ggplot2::labs(
    x = "Marginal threshold count k", y = expression(hat(F)^degree * (q)),
    title = "Threshold stability"
  ) +
  theme_simulation(8.3) +
  ggplot2::theme(
    legend.position = c(0.99, 0.99), legend.justification = c(1, 1),
    legend.direction = "vertical",
    legend.background = ggplot2::element_rect(fill = "white", colour = NA),
    legend.key.size = ggplot2::unit(0.8, "lines")
  )

profile_lines <- rbind(
  data.frame(profile[c("angle")], method = "Directional", estimate = profile$estimate),
  data.frame(profile[c("angle")], method = "Naive", estimate = profile$naive),
  data.frame(profile[c("angle")], method = "Independence", estimate = profile$independence)
)
profile_lines$method <- factor(
  profile_lines$method, levels = c("Directional", "Naive", "Independence")
)

p_profile <- ggplot2::ggplot() +
  ggplot2::geom_ribbon(
    data = profile, ggplot2::aes(angle, ymin = lower, ymax = upper),
    fill = unname(simulation_palette["proposed"]), alpha = 0.14
  ) +
  ggplot2::geom_line(
    data = profile_lines,
    ggplot2::aes(angle, estimate, colour = method, linetype = method), linewidth = 0.65
  ) +
  ggplot2::scale_colour_manual(values = c(
    "Directional" = unname(simulation_palette["proposed"]),
    "Naive" = unname(simulation_palette["naive"]),
    "Independence" = "#151515"
  )) +
  ggplot2::scale_linetype_manual(values = c("solid", "22", "42")) +
  ggplot2::scale_x_continuous(
    breaks = log(c(0.5, 1, 2)), labels = c("(1, 2)", "(1, 1)", "(2, 1)")
  ) +
  ggplot2::labs(
    x = "Direction q", y = expression(hat(F)^degree * (q)),
    title = "Normalized joint tail"
  ) +
  theme_simulation(8.3) +
  ggplot2::theme(legend.position = "bottom")

physical_long <- rbind(
  data.frame(physical["order"], method = "Directional", estimate = physical$estimate),
  data.frame(physical["order"], method = "Naive", estimate = physical$naive),
  data.frame(physical["order"], method = "Independence", estimate = physical$marginal_product)
)
physical_long$method <- factor(
  physical_long$method, levels = c("Directional", "Naive", "Independence")
)
threshold_labels <- paste0(physical$building / 1000, "/", physical$contents / 1000)

p_physical <- ggplot2::ggplot() +
  ggplot2::geom_ribbon(
    data = physical, ggplot2::aes(order, ymin = lower, ymax = upper),
    fill = unname(simulation_palette["proposed"]), alpha = 0.14
  ) +
  ggplot2::geom_line(
    data = physical_long,
    ggplot2::aes(order, estimate, colour = method, linetype = method), linewidth = 0.65
  ) +
  ggplot2::geom_point(
    data = physical_long, ggplot2::aes(order, estimate, colour = method), size = 1.2
  ) +
  ggplot2::scale_colour_manual(values = c(
    "Directional" = unname(simulation_palette["proposed"]),
    "Naive" = unname(simulation_palette["naive"]),
    "Independence" = "#151515"
  )) +
  ggplot2::scale_linetype_manual(values = c("solid", "22", "42")) +
  ggplot2::scale_x_continuous(breaks = physical$order, labels = threshold_labels) +
  ggplot2::scale_y_log10() +
  ggplot2::labs(
    x = "Threshold pair (USD thousands)",
    y = "Joint exceedance probability", title = "Monetary scale"
  ) +
  theme_simulation(8.3) +
  ggplot2::theme(
    legend.position = "bottom",
    axis.text.x = ggplot2::element_text(angle = 35, hjust = 1)
  )

shared_legend <- cowplot::get_legend(p_profile)
panels <- cowplot::plot_grid(
  p_stability,
  p_profile + ggplot2::theme(legend.position = "none"),
  p_physical + ggplot2::theme(legend.position = "none"),
  labels = c("(a)", "(b)", "(c)"), nrow = 1, label_size = panel_label_size, label_fontface = "plain",
  align = "h", axis = "tb", rel_widths = c(1, 1, 1.02)
)
figure <- cowplot::plot_grid(panels, shared_legend, ncol = 1,
                             rel_heights = c(1, 0.09))
save_simulation_figure(
  figure, file.path(figure_dir, "hurricane_ian_analysis.pdf"),
  width = 7.2, height = 3.1
)



## -------------------------------------------------------------------------
## Figure for the two checks: interval width, and the adjuster's assessment
## -------------------------------------------------------------------------

bootstrap_long <- rbind(
  data.frame(angle = bootstrap$angle[off_reference],
             sd = bootstrap$plug_in_sd[off_reference], source = "Plug-in"),
  data.frame(angle = bootstrap$angle[off_reference],
             sd = bootstrap$bootstrap_sd[off_reference], source = "Bootstrap")
)
bootstrap_long$source <- factor(bootstrap_long$source, levels = c("Plug-in", "Bootstrap"))

p_width <- ggplot2::ggplot(bootstrap_long,
                           ggplot2::aes(angle, sd, colour = source, linetype = source)) +
  ggplot2::geom_line(linewidth = 0.65) +
  ggplot2::geom_point(size = 1.2) +
  ggplot2::scale_colour_manual(values = c(
    "Plug-in" = unname(simulation_palette["proposed"]),
    "Bootstrap" = unname(simulation_palette["naive"]))) +
  ggplot2::scale_linetype_manual(values = c("solid", "22")) +
  ggplot2::scale_x_continuous(breaks = log(c(0.5, 1, 2)),
                              labels = c("(1, 2)", "(1, 1)", "(2, 1)")) +
  ggplot2::expand_limits(y = 0) +
  ggplot2::labs(x = "Direction q",
                y = expression("Standard deviation of " * log * hat(F)^degree * (q)),
                title = "Width of the intervals") +
  theme_simulation(8.3) +
  ggplot2::theme(legend.position = "bottom")

assessment <- do.call(rbind, lapply(seq_len(2L), function(j) {
  idx <- delta[, j] == 0L & !is.na(damage[, j]) & damage[, j] > 0
  data.frame(coordinate = c("Building", "Contents")[j],
             ratio = damage[idx, j] / effective_cap[idx, j])
}))
assessment$coordinate <- factor(assessment$coordinate, levels = c("Building", "Contents"))

p_assessment <- ggplot2::ggplot(assessment,
                                ggplot2::aes(ratio, colour = coordinate, linetype = coordinate)) +
  ggplot2::geom_vline(xintercept = 1, linewidth = 0.4, colour = "#4D4D4D") +
  ggplot2::stat_ecdf(geom = "step", linewidth = 0.65) +
  ggplot2::scale_colour_manual(values = c(
    "Building" = unname(simulation_palette["proposed"]),
    "Contents" = unname(simulation_palette["dabrowska"]))) +
  ggplot2::scale_linetype_manual(values = c("solid", "22")) +
  ggplot2::scale_x_continuous(breaks = c(0.5, 0.75, 1, 1.25, 1.5, 1.75, 2)) +
  ggplot2::coord_cartesian(xlim = c(0.5, 2)) +
  ggplot2::labs(x = "Assessed damage over the cap",
                y = "Empirical distribution function",
                title = "The assessment beyond the cap") +
  theme_simulation(8.3) +
  ggplot2::theme(legend.position = "bottom")

## What the assessments would give if read as the loss itself.
assessment_truth <- vapply(seq_len(nrow(physical_thresholds)), function(i) {
  q <- physical_thresholds[i, ]
  mean(damage[damage_available, 1L] > q[1L] & damage[damage_available, 2L] > q[2L])
}, numeric(1))
physical$assessment <- assessment_truth
substitution_long <- rbind(
  data.frame(physical["order"], method = "Directional", estimate = physical$estimate),
  data.frame(physical["order"], method = "Assessment", estimate = assessment_truth),
  data.frame(physical["order"], method = "Naive", estimate = physical$naive)
)
substitution_long$method <- factor(substitution_long$method,
                                   levels = c("Directional", "Assessment", "Naive"))

p_substitution <- ggplot2::ggplot(
  substitution_long, ggplot2::aes(order, estimate, colour = method, linetype = method)) +
  ggplot2::geom_line(linewidth = 0.65) +
  ggplot2::geom_point(size = 1.2) +
  ggplot2::scale_colour_manual(values = c(
    "Directional" = unname(simulation_palette["proposed"]),
    "Assessment" = unname(simulation_palette["dabrowska"]),
    "Naive" = unname(simulation_palette["naive"]))) +
  ggplot2::scale_linetype_manual(values = c("solid", "42", "22")) +
  ggplot2::scale_x_continuous(breaks = physical$order, labels = threshold_labels) +
  ggplot2::scale_y_log10() +
  ggplot2::labs(x = "Threshold pair (USD thousands)",
                y = "Joint exceedance probability",
                title = "Assessments as a substitute") +
  theme_simulation(8.3) +
  ggplot2::theme(legend.position = "bottom",
                 legend.key.width = ggplot2::unit(0.5, "cm"),
                 legend.text = ggplot2::element_text(size = 7),
                 axis.text.x = ggplot2::element_text(angle = 35, hjust = 1))

checks_figure <- cowplot::plot_grid(
  p_width, p_assessment, p_substitution, labels = c("(a)", "(b)", "(c)"), nrow = 1,
  label_size = panel_label_size, label_fontface = "plain", align = "h", axis = "tb",
  rel_widths = c(1, 1, 1.08)
)
save_simulation_figure(
  checks_figure, file.path(figure_dir, "hurricane_ian_checks.pdf"),
  width = 7.2, height = 3.2
)
utils::write.csv(assessment, file.path(result_dir, "hurricane_ian_assessment.csv"),
                 row.names = FALSE)

